#!/usr/bin/env python3
import json
import sys


def merge_patch(target, patch):
    if not isinstance(patch, dict):
        return patch
    if not isinstance(target, dict):
        target = {}
    result = dict(target)
    for key, value in patch.items():
        if value is None:
            result.pop(key, None)
        else:
            result[key] = merge_patch(result.get(key), value)
    return result


def load(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except OSError as e:
        sys.stderr.write("cannot read %s: %s\n" % (path, e.strerror or e))
    except ValueError as e:
        sys.stderr.write("invalid JSON in %s: %s\n" % (path, e))
    sys.exit(1)


def main(argv):
    if len(argv) != 3:
        sys.stderr.write("usage: merge_patch.py <target.json> <patch.json>\n")
        return 2
    target = load(argv[1])
    patch = load(argv[2])
    print(json.dumps(merge_patch(target, patch)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
